def __rejects_negative(obj):
    before = obj.minutes
    try:
        obj.minutes = -1
    except ValueError:
        return obj.minutes == before
    return False

def __rejects_initial():
    try:
        Duration(-1)
    except ValueError:
        return True
    return False

class Duration:
    def __init__(self, minutes):
        self.minutes = minutes

    @property
    def minutes(self):
        return self._minutes

    @minutes.setter
    def minutes(self, value):
        if value < 0:
            raise ValueError("minutes must be nonnegative")
        self._minutes = value
